// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Modpack) predicate.Modpack {
	return predicate.Modpack(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Modpack) predicate.Modpack {
	return predicate.Modpack(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Modpack) predicate.Modpack {
	return predicate.Modpack(sql.NotPredicates(p))
}
